entries[243621] = { ["name"] = "Verbleibende Hoffnung", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn eine hoffnungslose Reflexion vollständig geheilt wird, erhalten alle Heiler 'Verbleibende Hoffnung'. 'Verbleibende Hoffnung' stellt 5 Sek. lang alle 1 Sek. 2% Mana wieder her." }
